// Builds the BugIt-only icon set and the link-card image from the CANONICAL magnifier mascot
// (03-brand-logo-assets/logo-current/00-Master-SVG/BugIt-icon.svg, owner decision 2026-10-23).
// Output goes to public/bugit/. public/brand/ is generated by the shared brand sync and is not touched.
// Run: node scripts/build-bugit-mark.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const MASTER = path.resolve(root, "../../03-brand-logo-assets/logo-current/00-Master-SVG/BugIt-icon.svg");
const out = path.join(root, "public", "bugit");
fs.mkdirSync(out, { recursive: true });

// Static, tight-cropped square copy of the master: animation removed, same shapes.
let svg = fs.readFileSync(MASTER, "utf8").replace(/<style>[\s\S]*?<\/style>/, "");
svg = svg.replace('viewBox="0 0 100 100"', 'viewBox="12 18 76 76"').replace(/ class="blip-[a-z]+"/g, "");
fs.writeFileSync(path.join(out, "favicon.svg"), svg);
const uri = "data:image/svg+xml;base64," + Buffer.from(svg).toString("base64");

const browser = await chromium.launch();
const page = await browser.newPage();
async function png(size) {
  await page.setViewportSize({ width: size, height: size });
  await page.setContent(`<body style="margin:0;background:transparent"><img src="${uri}" width="${size}" height="${size}" style="display:block"></body>`);
  return page.screenshot({ omitBackground: true, clip: { x: 0, y: 0, width: size, height: size } });
}
const bufs = {};
for (const s of [16, 32, 48, 64, 180, 400, 512]) {
  bufs[s] = await png(s);
  fs.writeFileSync(path.join(out, s === 512 ? "logo-512.png" : `favicon-${s}.png`), bufs[s]);
}
// PNG-in-ICO: 16, 32, 48
const sizes = [16, 32, 48];
const head = Buffer.alloc(6); head.writeUInt16LE(1, 2); head.writeUInt16LE(sizes.length, 4);
let offset = 6 + 16 * sizes.length;
const dir = sizes.map((s) => {
  const e = Buffer.alloc(16); e[0] = s; e[1] = s; e.writeUInt16LE(1, 4); e.writeUInt16LE(32, 6);
  e.writeUInt32LE(bufs[s].length, 8); e.writeUInt32LE(offset, 12); offset += bufs[s].length; return e;
});
fs.writeFileSync(path.join(out, "favicon.ico"), Buffer.concat([head, ...dir, ...sizes.map((s) => bufs[s])]));

// 1200x630 link card, same layout as before, canonical mascot, no dash in the line.
const html = `<body style="margin:0;width:1200px;height:630px;overflow:hidden;font-family:'Segoe UI',Arial,Helvetica,sans-serif;background:
 radial-gradient(ellipse 520px 320px at 12% 18%,rgba(94,60,190,.75),transparent 70%),
 radial-gradient(ellipse 480px 300px at 86% 22%,rgba(210,70,160,.55),transparent 70%),
 linear-gradient(180deg,#14091f 0%,#0b0614 60%,#120818 100%);position:relative;color:#fff">
<div style="position:absolute;left:0;right:0;top:0;height:8px;background:linear-gradient(90deg,#ffd1ea,#ff5cb5,#9a5cff)"></div>
<img src="${uri}" style="position:absolute;left:78px;top:98px;width:190px;height:190px">
<div style="position:absolute;left:290px;top:80px;font-size:140px;font-weight:700;line-height:1.3;padding-bottom:10px;letter-spacing:-2px;background:linear-gradient(90deg,#ffe3f2,#ff8fd0 55%,#a56bff);-webkit-background-clip:text;color:transparent">BugIt</div>
<div style="position:absolute;left:293px;top:268px;font-size:28px;font-weight:700;color:#e6d4f5">by Taskivator</div>
<div style="position:absolute;left:97px;top:318px;font-size:64px;font-weight:800;line-height:1.1;width:900px">The QA agent that learns<br>your workflow.</div>
<div style="position:absolute;left:97px;top:482px;font-size:28px;line-height:1.4;color:#cdbfe0;width:900px">Turn rough test notes into polished, reviewed bug tickets filed to your tracker after your approval.</div>
<div style="position:absolute;right:96px;bottom:36px;font-size:26px;font-weight:700;color:#ff8fd0">bugit.dev</div></body>`;
await page.setViewportSize({ width: 1200, height: 630 });
await page.setContent(html);
fs.writeFileSync(path.join(out, "og-image.png"), await page.screenshot({ clip: { x: 0, y: 0, width: 1200, height: 630 } }));
await browser.close();
console.log("built public/bugit/: favicon.svg/.ico, favicon-16..400.png, logo-512.png, og-image.png");
